.specialist-section-global {
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 60px;
	width: 100%;
	max-width: 1440px;
	margin: 0 auto;
	padding: 0 60px;
	box-sizing: border-box;
  font-family: var(--font-family-figtree, Figtree), 'oxygen-regular', sans-serif;

}

.specialist-section-global .specialist-section__content {
	display: flex;
	flex-direction: column;
	gap: 5px;
	flex: 1;
	max-width: 849px;
}

.specialist-section-global .specialist-section__text {
	display: flex;
	flex-direction: column;
	gap: 0;
}

.specialist-section-global .specialist-section__title {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
  font-family: var(--font-family-figtree, Figtree), 'oxygen-regular', sans-serif;
	margin: 0;
	padding-bottom: 16px;
	font-weight: 600;
	color: #000000;
}

.specialist-section-global .specialist-section__title.t1 {
    font-size: 24px;
    line-height: 32px;
}

.specialist-section-global .specialist-section__title.t2 {
    font-size: 32px;
    line-height: 40px;
}

.specialist-section-global .specialist-section__title *{
	  display: inline-block;
    margin-bottom: 0;
}

.specialist-section-global .specialist-section__title *>strong{
    font-weight: 700;
    color: transparent;
    background: linear-gradient(90deg, #0435AC 0%, #162A59 100%) !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
}

.specialist-section-global .specialist-section__title .highlight{
	color: var(--primary)
}

.specialist-section-global .specialist-section__subtitle{
    font-size: 20px;
	color: #000
}

.specialist-section-global .specialist-section__description{
    display: -webkit-box;
    -webkit-line-clamp: 8;
    font-size: 18px;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
	color: #5B5B5F;
}

.specialist-section-global .specialist-section__description *{
	  display: inline-block;
    margin-bottom: 0;
}

.specialist-section-global .specialist-section__subtitle, .specialist-section-global .specialist-section__description {
	margin: 0;
	padding-bottom: 24px;
	max-width: 757px;
	font-weight: 400;
	line-height: 30px;
}

.specialist-section-global .specialist-section__ctas {
	display: flex;
	align-items: center;
	gap: 24px;
}

.specialist-section-global .specialist-section__button--primary.hapvida {
	display: -webkit-box;
    text-align: center;
    width: fit-content;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
    padding: 8px 10px;
    justify-content: center;
    align-items: center;
    border-radius: 3px 3px 12px 3px;
    background: var(--Current-In-prod-color-trust, #0435AC);
    border: 1px solid transparent;
    transition: all 0.3s ease;
    color: var(--Current-In-prod-color-default, #FFF);
    font-family: 'oxygen-regular';
    font-size: 16px;
    font-style: normal;
    font-weight: 700;
    line-height: 26px;
    cursor: pointer;
}

.specialist-section-global .specialist-section__button--primary.hapvida:active, 
.specialist-section-global .specialist-section__button--primary.hapvida:hover {
	color: var(--Current-In-prod-color-default, #FFF);
    background: var(--state-brand-primary-dark, #0B1243);
    text-decoration: none;
}

.specialist-section-global .specialist-section__button--secondary.hapvida {
	display: -webkit-box;
    text-align: center;
    width: fit-content;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
    text-overflow: ellipsis;
    padding: 8px 10px;
    justify-content: center;
    align-items: center;
    border-radius: 3px 3px 12px 3px;
    border-radius: 3px 3px 12px 3px;
    background: var(--Current-In-prod-color-default, #FFF);
    border: 1px solid var(--state-brand-primary-base, #1539AA);
    transition: all 0.3s ease;
    color: var(--state-brand-primary-base, #1539AA);
    font-family: 'oxygen-regular';
    font-size: 16px;
    font-style: normal;
    font-weight: 700;
    line-height: 26px;
    cursor: pointer;
}

.specialist-section-global .specialist-section__button--secondary.hapvida:active,
.specialist-section-global .specialist-section__button--secondary.hapvida:hover {
    background: var(--alpha-primary-alpha-10, rgba(37, 77, 219, 0.10));
    border: 1px solid transparent;
    text-decoration: none;
}

.specialist-section-global .specialist-section__button--primary.ppo {
	display: inline-flex;
    height: 44px;
    padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
    justify-content: center;
    align-items: center;
    gap: var(--spacing-spacing-4, 4px);
  font-family: var(--font-family-figtree, Figtree), 'oxygen-regular', sans-serif;
    font-size: 16px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.3s ease;
    color: var(--style-guide-v-0-primary-80, #0B2D50);
    border: 1px solid transparent;
    border-radius: var(--radii-radius-8, 8px);
    background: var(--Colour-ranges-Secondary-secondary-300, #88B9D7);
    font-family: var(--font-family-figtree, Figtree), 'oxygen-regular', sans-serif;

}

.specialist-section-global .specialist-section__button--primary.ppo:active, 
.specialist-section-global .specialist-section__button--primary.ppo:hover {
	color: var(--Colour-ranges-Absolute-Shades-absolute-shade-0, #FFF);
    background: var(--Colour-ranges-Primary-primary-500, #3149A4);
    border: 1px solid transparent;
    text-decoration: none;
}

.specialist-section-global .specialist-section__button--secondary.ppo {
	display: inline-flex;
    height: 44px;
    padding: var(--spacing-spacing-8, 8px) var(--spacing-spacing-10, 10px);
    justify-content: center;
    align-items: center;
    gap: var(--spacing-spacing-4, 4px);
    font-family: var(--font-family-figtree);
    font-size: 16px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.3s ease;
    color: var(--Colour-ranges-Primary-primary-700, #001453);
    border: 1px solid transparent;
    border-radius: var(--radii-radius-8, 8px);
    background: transparent;
    font-family: var(--font-family-figtree);
}

.specialist-section-global .specialist-section__button--secondary.ppo:active,
.specialist-section-global .specialist-section__button--secondary.ppo:hover {
    background: var(--alpha-primary-alpha-10, rgba(37, 77, 219, 0.10));
    border: 1px solid transparent;
    text-decoration: none;
}

.specialist-section-global .specialist-section__image {
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 0 0 531px;
	height: 352px;
	background: #E0E0CD;
	border-radius: 24px;
	overflow: hidden;
}

.specialist-section-global .specialist-section__image img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	display: block;
}

.specialist-section-global.specialist-section--image-only {
	display: inline-flex;
	max-width: none;
	padding: 0;
	padding-left: 60px;
    padding-right: 60px;
	vertical-align: top;
}

.specialist-section-global.specialist-section--image-only .specialist-section__image {
	width: 100%;
	flex: none;
	max-height: 340px;
}

.specialist-section-global .specialist-section__content .logo-group {
    display: flex;
    flex-wrap: wrap;
    gap: 20px;
    width: 100%;
}

.specialist-section-global .specialist-section__content .logo {
    max-height: 44px;
    object-fit: fill;
}

@media (min-width: 390px) and (max-width: 575px) {
	.specialist-section-global .specialist-section__ctas {
		flex-direction: column !important;
	}
}

@media (max-width: 991px) {
	.specialist-section-global.specialist-section--image-only {
		display: column;
		width: 100%;
		margin: 0 0 24px 0;
		padding: 0 24px;
	}
	.specialist-section-global.specialist-section--image-only .specialist-section__image {
		width: 100%;
		height: 260px;
	}
	.specialist-section-global{
		flex-direction: column;
		align-items: stretch;
		gap: 32px;
		padding: 0 24px;
	}
	.specialist-section-global .specialist-section__content {
		max-width: none;
		order: 2;
	}
	.specialist-section-global .specialist-section__image {
		order: 1;
		flex: none;
		width: 100%;
		height: 260px;
	}
	.specialist-section-global .specialist-section__title {
		padding-bottom: 16px;
	}



	.specialist-section-global .specialist-section__subtitle, .specialist-section-global .specialist-section__description {
		font-size: 16px;
		line-height: 28px;
		padding-bottom: 24px;
	}
	.specialist-section-global .specialist-section__ctas {
		flex-direction: row;
		align-items: stretch;
		gap: 16px;
	}
	.specialist-section-global .specialist-section__button {
		width: 100%;
	}
}
@media (min-width:768px) and (max-width:1399px){
    .specialist-section-global .specialist-section__title.t1 {
        font-size: 20px;
    }

    .specialist-section-global .specialist-section__title.t2 {
        font-size: 24px;
    }

    .specialist-section-global .specialist-section__description{
        font-size: 18px;
    }
}

@media (max-width:767px){
    .specialist-section-global .specialist-section__title.t1 {
        font-size: 20px;
    }

    .specialist-section-global .specialist-section__title.t2 {
        font-size: 24px;
    }

    .specialist-section-global .specialist-section__content .logo-group {
        flex-direction: column;
			  align-items: start;
        gap: 24px;
    }

    .specialist-section-global .specialist-section__title {
        -webkit-line-clamp: 4;
    }

    .specialist-section-global .specialist-section__description{
        -webkit-line-clamp: 16;
        font-size: 18px;
    }

    .specialist-section-global .specialist-section__image img {
        object-position: 13% center;
    }
}

