(function () {
  var overlay = fragmentElement.querySelector('.hapvida-search-overlay');
  if (!overlay) return;

  var justOpened = false;

  function openOverlay() {
    justOpened = true;
    overlay.classList.add('is-open');
    setTimeout(function () {
      var input = overlay.querySelector('input[type="text"]');
      if (input) input.focus();
      justOpened = false;
    }, 50);
  }

  function closeOverlay() {
    overlay.classList.remove('is-open');
    document.dispatchEvent(new CustomEvent('hapvida:searchClosed'));
  }

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && overlay.classList.contains('is-open')) {
      closeOverlay();
    }
  });

  document.addEventListener('click', function (e) {
    if (!overlay.classList.contains('is-open')) return;
    if (justOpened) return;
    if (!overlay.contains(e.target)) {
      closeOverlay();
    }
  });

  document.addEventListener('hapvida:openSearch', openOverlay);
  document.addEventListener('hapvida:closeSearch', closeOverlay);
})();

(function () {
	function validateSearch(input) {
		const value = input.value.trim();

		if (value.length < 10) {
			//alert('Digite pelo menos 10 caracteres para pesquisar.');
			input.focus();
			return false;
		}

		return true;
	}

	document.addEventListener('click', function (event) {
		const button = event.target.closest('.hapvida-sb__submit');

		if (!button) {
			return;
		}

		const container = button.closest('.hapvida-sb__row');

		if (!container) {
			return;
		}

		const input = container.querySelector('.hapvida-sb__input[name="q"]');

		if (!input || !validateSearch(input)) {
			event.preventDefault();
			event.stopPropagation();
			event.stopImmediatePropagation();
		}
	}, true);

	document.addEventListener('keydown', function (event) {
		const input = event.target.closest('.hapvida-sb__input[name="q"]');

		if (!input || event.key !== 'Enter') {
			return;
		}

		if (!validateSearch(input)) {
			event.preventDefault();
			event.stopPropagation();
			event.stopImmediatePropagation();
		}
	}, true);
})();;

