(function () {
    const SCRIPT_ID = 'sienna-accessibility-script';
    const GLOBAL_LISTENER_FLAG = '__siennaAltShortcutRegistered';
    const GLOBAL_CONTROLLER = '__siennaAccessibilityController';

    if (!window[GLOBAL_CONTROLLER]) {
        window[GLOBAL_CONTROLLER] = {
            lastFocused: null,
            resetting: false,
            observerRegistered: false,
            enhanceTimer: null
        };
    }

    const state = window[GLOBAL_CONTROLLER];

    const CLOSE_SELECTOR = [
        '.asw-menu-close',
        '[aria-label="Close"]',
        '[aria-label="Fechar"]',
        '[title="Close"]',
        '[title="Fechar"]'
    ].join(',');

    const RESET_SELECTOR = [
        '.asw-menu-reset',
        '.asw-menu-reset-footer-btn',
        '[aria-label="Reset settings"]',
        '[aria-label="Redefinir acessibilidade"]',
        '[title="Reset settings"]',
        '[title="Redefinir acessibilidade"]'
    ].join(',');

    const KEYBOARD_ACTION_SELECTOR = [
        '.asw-plus',
        '.asw-minus',
        '.asw-btn',
        '.asw-menu-close',
        '.asw-menu-reset',
        '.asw-menu-reset-footer-btn',
        'button:not([disabled])',
        '[role="button"]:not([aria-disabled="true"])'
    ].join(',');

    function loadSiennaScript() {
        if (document.getElementById(SCRIPT_ID)) {
            return;
        }

        const script = document.createElement('script');

        script.id = SCRIPT_ID;
        script.src = 'https://cdn.jsdelivr.net/npm/sienna-accessibility/dist/sienna-accessibility.umd.js';
        script.async = true;
        script.setAttribute('data-lang', 'pt'); 

        script.onload = function () {
            setTimeout(enhanceMenu, 300);
            setTimeout(enhanceMenu, 1000);
            setTimeout(enhanceMenu, 2000);
        };

        document.head.appendChild(script);
    }

    function getMenu() {
        return document.querySelector('.asw-menu');
    }

    function isVisible(element) {
        if (!element) return false;

        const style = window.getComputedStyle(element);

        return (
            style.display !== 'none' &&
            style.visibility !== 'hidden' &&
            style.opacity !== '0' &&
            element.getClientRects().length > 0
        );
    }

    function getOpenMenu() {
        const menu = getMenu();
        return menu && isVisible(menu) ? menu : null;
    }

    function getSiennaButton() {
        return (
            document.querySelector('.asw-menu-btn') ||
            document.querySelector('.sienna-accessibility-widget button')
        );
    }

    function getVisibleAccessibilityButton() {
        const buttons = document.querySelectorAll(
            '[data-sienna-custom-trigger], .accessibility-button'
        );

        for (let i = 0; i < buttons.length; i++) {
            if (isVisible(buttons[i])) {
                return buttons[i];
            }
        }

        return null;
    }

    function setAttr(element, name, value) {
        if (element && element.getAttribute(name) !== value) {
            element.setAttribute(name, value);
        }
    }

    function isActivationKey(event) {
        return event.key === 'Enter' || event.key === ' ';
    }

    function normalizeElement(target) {
        if (!target) {
            return null;
        }

        if (target.nodeType === Node.ELEMENT_NODE) {
            return target;
        }

        return target.parentElement || null;
    }

    function closestWithin(element, selector, boundary) {
        const normalized = normalizeElement(element);

        if (!normalized || !boundary || !boundary.contains(normalized)) {
            return null;
        }

        const found = normalized.closest(selector);

        if (found && boundary.contains(found)) {
            return found;
        }

        return null;
    }

    function makeElementKeyboardButton(element, label) {
        if (!element) {
            return;
        }

        if (!element.hasAttribute('tabindex')) {
            element.setAttribute('tabindex', '0');
        }

        if (!element.hasAttribute('role')) {
            element.setAttribute('role', 'button');
        }

        if (label && !element.hasAttribute('aria-label')) {
            element.setAttribute('aria-label', label);
        }
    }

    function getFocusable(container) {
        const selector = [
            'a[href]',
            'button:not([disabled])',
            'input:not([disabled])',
            'select:not([disabled])',
            'textarea:not([disabled])',
            '[tabindex]:not([tabindex="-1"])',
            '[role="button"]:not([aria-disabled="true"])'
        ].join(',');

        return Array.prototype.filter.call(
            container.querySelectorAll(selector),
            isVisible
        );
    }

    function makeTextsFocusable(menu) {
        const elements = menu.querySelectorAll(
            '.asw-menu-reset, .asw-menu-title, .asw-card-title, .asw-label, .asw-amount'
        );

        Array.prototype.forEach.call(elements, function (element) {
            if (!element.hasAttribute('tabindex')) {
                element.setAttribute('tabindex', '0');
            }
        });
    }

    function addShortcutInfo(menu) {
        if (menu.querySelector('.sienna-shortcut-info')) {
            return;
        }

        const shortcut = document.createElement('div');

        shortcut.className = 'sienna-shortcut-info';
        shortcut.setAttribute('aria-label', 'Atalho do widget: ALT mais A');

        shortcut.innerHTML =
            '<span class="sienna-shortcut-info__label">Atalho do widget:</span>' +
            '<kbd class="sienna-shortcut-info__key">ALT</kbd>' +
            '<span class="sienna-shortcut-info__plus" aria-hidden="true">+</span>' +
            '<kbd class="sienna-shortcut-info__key">A</kbd>';

        const header = menu.querySelector('.asw-menu-header, .asw-header');
        const content = menu.querySelector('.asw-menu-content');

        if (header && header.parentNode === menu) {
            header.insertAdjacentElement('afterend', shortcut);
            return;
        }

        if (content && content.parentNode === menu) {
            menu.insertBefore(shortcut, content);
            return;
        }

        menu.insertBefore(shortcut, menu.firstChild);
    }

    function focusFirstInMenu() {
        const menu = getOpenMenu();

        if (!menu) {
            return;
        }

        enhanceMenu();

        const first =
            menu.querySelector('.asw-menu-title') ||
            getFocusable(menu)[0];

        if (first && first.focus) {
            first.focus({ preventScroll: true });
        }
    }

    function trapFocus(event, menu) {
        const focusable = getFocusable(menu);

        if (!focusable.length) {
            return;
        }

        const first = focusable[0];
        const last = focusable[focusable.length - 1];

        if (!menu.contains(document.activeElement)) {
            event.preventDefault();
            first.focus({ preventScroll: true });
            return;
        }

        if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus({ preventScroll: true });
            return;
        }

        if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus({ preventScroll: true });
        }
    }

    function restoreFontSize() {
        Array.prototype.forEach.call(
            document.querySelectorAll('[data-asw-org-font-size]'),
            function (element) {
                const originalSize = element.getAttribute('data-asw-org-font-size');

                if (originalSize) {
                    element.style.fontSize = originalSize + 'px';
                }

                element.removeAttribute('data-asw-org-font-size');
            }
        );

        Array.prototype.forEach.call(
            document.querySelectorAll('.asw-amount'),
            function (element) {
                element.textContent = '100%';
            }
        );
    }

    function triggerClick(element) {
        if (!element) {
            return;
        }

        try {
            element.click();
        } catch (error) {
            try {
                element.dispatchEvent(
                    new MouseEvent('click', {
                        bubbles: true,
                        cancelable: true,
                        view: window
                    })
                );
            } catch (ignored) {}
        }
    }

    function forceHideMenu(menu) {
        if (!menu) {
            return;
        }

        menu.style.display = 'none';
        menu.setAttribute('aria-hidden', 'true');

        setTimeout(function () {
            const target = getVisibleAccessibilityButton() || state.lastFocused;

            if (target && target.focus) {
                target.focus({ preventScroll: true });
            }
        }, 100);
    }

    function closeSienna() {
        const menu = getOpenMenu();

        if (!menu) {
            return;
        }

        const closeButton =
            menu.querySelector(CLOSE_SELECTOR) ||
            menu.querySelector('.asw-menu-close');

        if (closeButton) {
            triggerClick(closeButton);

            setTimeout(function () {
                if (getOpenMenu()) {
                    forceHideMenu(menu);
                }
            }, 120);
        } else {
            forceHideMenu(menu);
        }

        setTimeout(function () {
            const target = getVisibleAccessibilityButton() || state.lastFocused;

            if (target && target.focus) {
                target.focus({ preventScroll: true });
            }
        }, 160);
    }

    function resetSienna(button, menu) {
        if (state.resetting) {
            return;
        }

        state.resetting = true;

        triggerClick(button);

        if (button.classList.contains('asw-menu-reset-footer-btn')) {
            const headerButton = menu.querySelector('.asw-menu-reset');

            if (headerButton && headerButton !== button) {
                setTimeout(function () {
                    triggerClick(headerButton);
                }, 50);
            }
        }

        setTimeout(restoreFontSize, 200);
        setTimeout(restoreFontSize, 600);

        setTimeout(function () {
            state.resetting = false;
            enhanceMenu();
        }, 800);
    }

    function isCloseElement(element, menu) {
        if (!element || !menu || !menu.contains(element)) {
            return false;
        }

        if (element.matches(CLOSE_SELECTOR) || element.closest(CLOSE_SELECTOR)) {
            return true;
        }

        const text = (element.textContent || '').trim().toLowerCase();

        return text === 'close' || text === 'fechar' || text === '×' || text === 'x';
    }

    function isResetElement(element, menu) {
        if (!element || !menu || !menu.contains(element)) {
            return false;
        }

        if (element.matches(RESET_SELECTOR) || element.closest(RESET_SELECTOR)) {
            return true;
        }

        const text = (element.textContent || '').trim().toLowerCase();

        return (
            text === 'reset settings' ||
            text === 'resetar' ||
            text === 'redefinir' ||
            text === 'redefinir acessibilidade' ||
            text === 'redefinir configurações' ||
            text === 'limpar configurações'
        );
    }

    function getKeyboardActionTarget(event, menu) {
        const eventTarget = normalizeElement(event.target);
        const activeTarget = normalizeElement(document.activeElement);

        return (
            closestWithin(eventTarget, KEYBOARD_ACTION_SELECTOR, menu) ||
            closestWithin(activeTarget, KEYBOARD_ACTION_SELECTOR, menu)
        );
    }

    function activateKeyboardTarget(target, menu) {
        if (!target || !menu) {
            return;
        }

        if (isCloseElement(target, menu)) {
            closeSienna();
            return;
        }

        if (isResetElement(target, menu)) {
            resetSienna(target, menu);
            return;
        }

        triggerClick(target);

        setTimeout(enhanceMenu, 100);
        setTimeout(enhanceMenu, 300);
    }

    function patchKeyboardOnButtons(menu) {
        Array.prototype.forEach.call(
            menu.querySelectorAll(KEYBOARD_ACTION_SELECTOR),
            function (button) {
                if (button.matches(CLOSE_SELECTOR)) {
                    makeElementKeyboardButton(button, 'Fechar acessibilidade');
                } else if (button.matches(RESET_SELECTOR)) {
                    makeElementKeyboardButton(button, 'Redefinir acessibilidade');
                } else {
                    makeElementKeyboardButton(button);
                }

                if (button.getAttribute('data-kb-patched') === '1') {
                    return;
                }

                button.setAttribute('data-kb-patched', '1');

                button.addEventListener('keydown', function (event) {
                    if (!isActivationKey(event)) {
                        return;
                    }

                    event.preventDefault();
                    event.stopPropagation();

                    activateKeyboardTarget(button, menu);
                });
            }
        );
    }

    function patchResetButton(menu) {
        const buttons = menu.querySelectorAll(RESET_SELECTOR);

        Array.prototype.forEach.call(buttons, function (button) {
            makeElementKeyboardButton(button, 'Redefinir acessibilidade');

            if (button.getAttribute('data-reset-patched') === '1') {
                return;
            }

            button.setAttribute('data-reset-patched', '1');

            button.addEventListener('click', function () {
                setTimeout(restoreFontSize, 200);
                setTimeout(restoreFontSize, 600);
            });
        });
    }

    function patchCloseButton(menu) {
        const buttons = menu.querySelectorAll(CLOSE_SELECTOR);

        Array.prototype.forEach.call(buttons, function (button) {
            makeElementKeyboardButton(button, 'Fechar acessibilidade');
        });
    }

    function enhanceMenu() {
        const menu = getMenu();

        if (!menu) {
            return;
        }

        setAttr(menu, 'role', 'dialog');
        setAttr(menu, 'aria-modal', 'true');

        addShortcutInfo(menu);
        makeTextsFocusable(menu);
        patchCloseButton(menu);
        patchResetButton(menu);
        patchKeyboardOnButtons(menu);
    }

    function scheduleEnhanceMenu() {
        clearTimeout(state.enhanceTimer);

        state.enhanceTimer = setTimeout(function () {
            enhanceMenu();
        }, 80);
    }

    function registerMenuObserver() {
        if (state.observerRegistered || !document.body) {
            return;
        }

        state.observerRegistered = true;

        const observer = new MutationObserver(function () {
            if (getMenu()) {
                scheduleEnhanceMenu();
            }
        });

        observer.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['class', 'style', 'aria-hidden']
        });

        state.observer = observer;
    }

    function openSienna() {
        state.lastFocused = document.activeElement;

        let attempts = 0;

        function tryOpen() {
            const siennaButton = getSiennaButton();

            if (siennaButton) {
                triggerClick(siennaButton);

                setTimeout(enhanceMenu, 150);
                setTimeout(focusFirstInMenu, 250);
                setTimeout(enhanceMenu, 500);
                setTimeout(enhanceMenu, 1000);

                return;
            }

            attempts++;

            if (attempts <= 10) {
                setTimeout(tryOpen, 150);
                return;
            }

            console.warn('[Sienna] Botão do widget ainda não encontrado.');
        }

        tryOpen();
    }

    function toggleSienna() {
        if (getOpenMenu()) {
            closeSienna();
        } else {
            openSienna();
        }
    }

    function registerFragmentButtons() {
        if (typeof fragmentElement === 'undefined' || !fragmentElement) {
            return;
        }

        const buttons = fragmentElement.querySelectorAll(
            '.accessibility-button, [data-sienna-custom-trigger]'
        );

        Array.prototype.forEach.call(buttons, function (button) {
            if (button.getAttribute('data-sienna-fragment-patched') === '1') {
                return;
            }

            button.setAttribute('data-sienna-fragment-patched', '1');

            if (!button.hasAttribute('data-sienna-custom-trigger')) {
                button.setAttribute('data-sienna-custom-trigger', 'true');
            }

            button.addEventListener('click', function (event) {
                event.preventDefault();
                toggleSienna();
            });

            button.addEventListener('keydown', function (event) {
                if (isActivationKey(event)) {
                    event.preventDefault();
                    event.stopPropagation();
                    toggleSienna();
                }
            });
        });
    }

    function registerGlobalEvents() {
        if (window[GLOBAL_LISTENER_FLAG]) {
            return;
        }

        window[GLOBAL_LISTENER_FLAG] = true;

        document.addEventListener(
            'keydown',
            function (event) {
                const key = event.key ? event.key.toLowerCase() : '';

                const isAltA =
                    event.altKey &&
                    !event.ctrlKey &&
                    !event.shiftKey &&
                    !event.metaKey &&
                    (key === 'a' || event.code === 'KeyA');

                if (isAltA) {
                    const visibleButton = getVisibleAccessibilityButton();

                    if (!visibleButton) {
                        return;
                    }

                    event.preventDefault();
                    event.stopPropagation();

                    toggleSienna();
                    return;
                }

                const menu = getOpenMenu();

                if (!menu) {
                    return;
                }

                if (isActivationKey(event)) {
                    const target = getKeyboardActionTarget(event, menu);

                    if (target) {
                        event.preventDefault();
                        event.stopPropagation();

                        if (event.stopImmediatePropagation) {
                            event.stopImmediatePropagation();
                        }

                        activateKeyboardTarget(target, menu);
                        return;
                    }
                }

                if (event.key === 'Escape') {
                    event.preventDefault();
                    event.stopPropagation();

                    closeSienna();
                    return;
                }

                if (event.key === 'Tab') {
                    trapFocus(event, menu);
                }
            },
            true
        );

        document.addEventListener(
            'click',
            function (event) {
                const menu = getMenu();

                if (menu && menu.contains(event.target)) {
                    setTimeout(enhanceMenu, 100);
                    setTimeout(enhanceMenu, 300);
                }
            },
            true
        );
    }

    if ('speechSynthesis' in window && !window.__siennaSpeechLangPatched) { window.__siennaSpeechLangPatched = true; var __siennaTextMap = { 'Sienna Screen Reader Enabled': 'Leitor de tela Sienna ativado', 'Sienna Screen Reader Disabled': 'Leitor de tela Sienna desativado' }; var __siennaOriginalSpeak = window.speechSynthesis.speak.bind(window.speechSynthesis); window.speechSynthesis.speak = function (utterance) { if (__siennaTextMap[utterance.text]) { utterance.text = __siennaTextMap[utterance.text]; } utterance.lang = 'pt-BR'; var voices = window.speechSynthesis.getVoices(); var ptVoice = voices.find(function (v) { return v.lang && v.lang.indexOf('pt') === 0; }); if (ptVoice) { utterance.voice = ptVoice; } return __siennaOriginalSpeak(utterance); }; }loadSiennaScript();
    registerFragmentButtons();
    registerGlobalEvents();
    registerMenuObserver();

    setTimeout(enhanceMenu, 600);
    setTimeout(enhanceMenu, 1800);
    setTimeout(enhanceMenu, 3000);
})();;

