  text-decoration: none;
 object-fit:cover;
}

.botao-flutuante-container p {
  padding-right: 5px;
  margin: 0;
}

.textPromo {
  display: none;
  opacity: 0;
	margin:0 20px;
}

.botao-flutuante-container a:hover .textPromo {
  display: block;
  animation: fadeIn 0.5s ease-in-out forwards;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
.botao-flutuante-container span {
  color: #26cb3d;
  text-align: left;
}

.botao-flutuante {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #26cb3d;
  border-radius: 50%;
  padding: 0;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
  --webkit-box-align: center;
  --webkit-box-pack: center;
  background-position: center center;
  width: 48px;
  height: 48px;
	overflow:hidden;
	background-color:${configuration.colorBtn};
}

.botao-flutuante img {
  max-width: 38px;
