js:
$(document).ready(function () {
    var $cardsContainer = $('#cards-container');
    var $showMoreBtn = $('.resultado');
    var $cards = $cardsContainer.find('.campoWrapper2');

    // Exibe inicialmente até 6 cartões
    $cards.slice(0, 6).removeClass('hidden');

    // Verifica se há mais de 6 cartões
    if ($cards.length > 6) {
        // Se sim, exibe o botão
        $showMoreBtn.removeClass('hidden');

        // Oculta cartões além dos 6 primeiros
        $cards.slice(6).addClass('hidden');
    }

    // Adiciona um evento de clique ao botão
    $showMoreBtn.click(function () {
        // Encontra os próximos 6 cartões ocultos
        var $hiddenCards = $cards.filter('.hidden:lt(6)');

        // Exibe os próximos 6 cartões
        $hiddenCards.removeClass('hidden');

        // Atualiza o botão com base na quantidade restante de cartões
        if ($cards.filter('.hidden').length === 0) {
            $showMoreBtn.addClass('hidden');
        }

        // Foca no primeiro novo cartão visível
        var $newCards = $cardsContainer.find('.cardClicavel:visible');
        if ($newCards.length > 0) {
            $newCards.first().attr('tabindex', '0').focus();
        }
    });
});;

