var root = typeof fragmentElement !== "undefined" ? fragmentElement : document;

var modal = root.querySelector('#telemedicina_especialidades_modal, [id$="telemedicina_especialidades_modal"]');
var btn1 = root.querySelector('#open_modal_especialidades, [id$="open_modal_especialidades"]');
var btnclose3 = root.querySelector(".btn-close.btn_close_x");
var btnclose4 = root.querySelector(".button_ok_close_two");

if (modal && btn1) {
    var openModal = function () {
        modal.style.display = "block";
    };

    var closeModal = function () {
        modal.style.display = "none";
    };

    btn1.addEventListener("click", openModal);

    if (btnclose3) {
        btnclose3.addEventListener("click", closeModal);
    }

    if (btnclose4) {
        btnclose4.addEventListener("click", closeModal);
    }

    root.addEventListener("click", function (event) {
        if (event.target === modal) {
            closeModal();
        }
    });
}
;

