js:
var root = typeof fragmentElement !== "undefined" ? fragmentElement : document;

// Get the modal
var modal = root.querySelector('#modaldlipa, [id$="modaldlipa"]');

// Get the button that opens the modal
var btn1 = root.querySelector('#modalBtn1123, [id$="modalBtn1123"]');

// Get the <span> element that closes the modal
var btnclose5 = root.querySelector(".xxxxxxxxxxx");
var btnclose6 = root.querySelector(".xxxxxxxxx-w");

if (modal && btn1) {
    var openModal = function () {
        modal.style.display = "block";
    };

    var closeModal = function () {
        modal.style.display = "none";
    };

    // When the user clicks the button, open the modal
    btn1.addEventListener("click", openModal);

    // When the user clicks on <span> (x), close the modal
    if (btnclose5) {
        btnclose5.addEventListener("click", closeModal);
    }

    if (btnclose6) {
        btnclose6.addEventListener("click", closeModal);
    }

    // When the user clicks anywhere outside of the modal, close it
    root.addEventListener("click", function (event) {
        if (event.target === modal) {
            closeModal();
        }
    });
}
;

