.swiper {
        width: 100%;
        height: 100%;
      }

      .swiper-slide {
        text-align: center;
        font-size: 18px;
        background: #fff;

        /* Center slide text vertically */
        display: -webkit-box;
        display: -ms-flexbox;
        display: -webkit-flex;
        display: flex;
        -webkit-box-pack: center;
        -ms-flex-pack: center;
        -webkit-justify-content: center;
        justify-content: center;
        -webkit-box-align: center;
        -ms-flex-align: center;
        -webkit-align-items: center;
        align-items: center;
      }

      .swiper-slide img {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
      }

.swiper-button-next, .swiper-button-prev{
		background-color: black;
		padding: 21px !important;
		border-radius: 25px;
}

.swiper-button-next{right: 90px !important;}
.swiper-button-prev{left: 90px !important;}

.swiper-button-next::after, .swiper-button-prev::after{
	  font-size: 16px;
    color: white;
}
.swiperBannerMob .swiper-pagination{
  position: static;
}
.swiperBannerMob .swiper-pagination .swiper-pagination-bullet{
	margin:1%;
}
.swiperBannerMob .swiper-pagination .swiper-pagination-bullet-active{
    width: 3%;
    border-radius: 5px;
	  border-color: transparent;
		background-color: #EC6E0C;
}
.swiperBannerMob .swiper-wrapper .swiper-slide div{
	width: 100%;
}
.swiperBannerMob .swiper-wrapper .swiper-slide img{
	min-height: 217px;
	max-height: 416px;
}

js:
Pagina.pronta(function () {
	var swiperServicos = new Swiper(".swiperBannerMob", {
		freeMode: false,
		centeredSlides: false,
		pagination: {
			el: ".swiper-pagination",
			type: 'bullets',
			clickable: true,
		}
	});
});;

