js:
$(document).ready(function () {
		// Para fins de teste no Postman
	  // console.log("groupId: ", window.__SITE__.codigo);
    // console.log("userId: ", '');
    //console.log("companyId: ", '');

$("#submitBtn").click(function (event) {
    event.preventDefault();
    if (validate()) {
      $(this).prop("disabled", true);
			submitForm();
    }
});

});

function validate() {

    var isValid = true;

    isValid &= validateField("#nomeUser");
    isValid &= validateEmail("#emailUser");

    return isValid;
}

function validateField(selector) {
    removeError(selector);
    if ($(selector).val() == undefined || $(selector).val().trim() === "") {
        $("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }
    return true;
}

function validateEmail(selector) {
	removeError(selector);
	var email = $(selector).val().trim();
	var emailRegex = /^[a-zA-Z0-9._-]+@[a-zA-Z0-9.-]+\.(com|com\.br)$/;

	if (email === "") {
		$("<p class='error-message'>*Campo obrigatório</p>").insertAfter(selector);
		$(selector).addClass("error-border").focus();
		return false;
	} else if(!emailRegex.test(email)) {
		$("<p class='error-message'>*Email inválido</p>").insertAfter(selector);
		$(selector).addClass("error-border").focus();
		return false;
	}
	return true;
}

function removeError(selector) {
    $(selector).siblings(".error-message").remove();
    $(selector).removeClass("error-border");
}

function showLoad(){
    $('#loadingDiv').show();
}

function hideLoad(){
    $('#loadingDiv').hide();
}

function submitForm() {

    showLoad();

    setTimeout(function() {
    var apiRUL = window.location.origin.toString() + "/api/servicos/listaDinamica/gravar-lista-dinamica";
    let nomeUser = $("#nomeUser").val();
    let emailUser = $("#emailUser").val();

	  // [INICIO - Não remover os campos abaixo]
    let tabelaDinamica = configuration.tabelaDinamica // alterar de acordo com a tabela dinâmica 
    let groupId = configuration.idSite === "" ? window.__SITE__.codigo : configuration.idSite;
    let userId = '';
    let companyId = '';
    // [FIM]

    var data = JSON.stringify({
        nomeUser: nomeUser,
        emailUser: emailUser,
	      // [INICIO - Não remover os campos abaixo]
        tabelaDinamica: tabelaDinamica,
        groupId: groupId,
        userId: userId,
        companyId: companyId
			  // [FIM]
    });

    $.ajax(apiRUL, {
        method: "POST",
        contentType: "application/json",
        data: data,
				success: function (data) {
	          console.log("", data.success)
						if (data.success) {
							// Mensagem de Sucesso para o Cliente
							$(".blocoMsgSucess").css({ display: "flex" });
						} else {
							// Mensagem de Erro para o Cliente
              $(".blocoMsgError").css({ display: "flex" });
						}
              $("#formulario").hide();
              hideLoad();
	       },
         error: function (xhr, status, error) {
							// Mensagem de Erro para o Cliente em caso de erro na requisição
              $("#formulario").hide();
							$(".blocoMsgError").css({ display: "flex" });
							console.error("Erro na requisição:", error);
					},
				});
    }, 2000);
};

