$('.clickshow').click(function(){
  if ($(this).find('.subtextoDuvidas').hasClass('show_sectionfield')){
    $('.clickshow').find('.subtextoDuvidas').removeClass('show_sectionfield');
		$('.clickshow').find('.subtextoDuvidas').removeClass('campoGuiaStyle');
  }

  else {
    $('.clickshow').find('.subtextoDuvidas').removeClass('show_sectionfield');
    $(this).find('.subtextoDuvidas').addClass('show_sectionfield');
		$(this).find('.clickshow').addClass('campoGuiaStyle');
  }
});;

