.botao-flutuante-container {
  position: fixed;
  bottom: 90px;
  right: 20px;
  z-index: 1000;
  border: 5px solid #26cb3d;
  border-radius: 36px;
  background: white;
  box-shadow: 0px 0px 10px 0px rgba(0, 0, 0, 0.3490196078);
  padding: 5px;
  display: flex;
  --webkit-box-align: center;
  align-items: center;
  font-family: "oxygen-regular";
  color: #000;
  font-size: 1rem;
	overflow:hidden;
}

.botao-flutuante-container a {
  display: flex;
  align-items: center;
  justify-content: center;
  --webkit-box-align: center;
  --webkit-box-pack: center;
  background-position: center center;
  font-family: "oxygen-regular";
  color: #000;
  font-weight: 900;
  text-align: left;
  text-decoration: none;
 object-fit:cover;
}

.botao-flutuante-container p {
  padding-right: 5px;
  margin: 0;
}

.textPromo {
  display: none;
  opacity: 0;
	margin:0 20px;
}

.botao-flutuante-container a:hover .textPromo {
  display: block;
  animation: fadeIn 0.5s ease-in-out forwards;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
.botao-flutuante-container span {
  color: #26cb3d;
  text-align: left;
}

.botao-flutuante {
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #26cb3d;
  border-radius: 50%;
  padding: 0;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.3);
  --webkit-box-align: center;
  --webkit-box-pack: center;
  background-position: center center;
  width: 48px;
  height: 48px;
	overflow:hidden;
	background-color:${configuration.colorBtn};
}

.botao-flutuante img {
  max-width: 38px;
    max-height: 38px;
    width: 48px;
    height: 48px;
	object-fit:cover;
}
html .contraste-body div.botao-flutuante-container{
	background-color:#26cb3d !important;
	color:#fff !important;
}
