// ------------step-wizard-------------
$(document).ready(function () {



    $('#cpf').mask('000.000.000-00');
    $('#cnpj').mask('00.000.000/0000-00'); 
    $('#cepPF').mask('00000-000');
    $('#cepPJ').mask('00000-000');
    $('#telefonePF').mask('(00) 000-0000');
    $('#telefonePJ').mask('(00) 000-0000');
    $('#celularPF').mask('(00) 0000-0000');
    $('#celularPJ').mask('(00) 0000-0000');
    $('#dataDeNascimentoPF').mask('00/00/0000');
    $('#anoDeFormacao').mask('0000');

  $("input[name='Perfil']").change(function() {
    $(".step1PF").toggleClass("hide");
    $(".step2PF").toggleClass("hide");
    $(".step3PF").toggleClass("hide");
    $(".step1PJ").toggleClass("hide");
    $(".step2PJ").toggleClass("hide");
    $(".step3PJ").toggleClass("hide");
  });

    $('.nav-tabs > li a[title]').tooltip();

    //Wizard
    $('a[data-toggle="tab"]').on('shown.bs.tab', function (e) {

        var target = $(e.target);
        if (target.parent().hasClass('disabled')) {
            return false;
        }
    });

    $(".next-step").click(function (e) {

        var active = $('.wizard .nav-tabs li.active');
        var currStep = active.children().attr("aria-controls");
        var selectedProfile = $("input[name='Perfil']:checked").val();
        var isValid = false;

        if(currStep === "step1"){
            if (selectedProfile === "PF") {
                isValid = validateStep1PF();
            } else {
                isValid = validateStep1PJ();
            }

            if (isValid) {
                $('.prev-step').css('opacity', 1);
            }

        }

        if(currStep === "step2"){
            if (selectedProfile === "PF") {
                isValid = validateStep2PF();
            } else {
                isValid = validateStep2PJ();
            }
            if (isValid) {
                $('.next-step').css('opacity', 0.5);
            }
        }

        if(currStep === "step3"){
            if (selectedProfile === "PF") {
                isValid = validateStep3PF();
            } else {
                isValid = true;
            }
        }

        if (isValid) {
            active.next().removeClass('disabled');
            nextTab(active);
        }
    });

    $(".prev-step").click(function (e) {

        var active = $('.wizard .nav-tabs li.active');
        prevTab(active);

    });

    $("#submitBtnPF").click(function () {
        if (validateStep3PF()) {
            var recaptchaResponse = $("#hiddenRecaptcha_pf").val();
            if (recaptchaResponse === "") {
                $("<p class='error-message'>Por favor, marque o ReCaptcha.</p>").insertAfter(".recaptcha");
            } else { 
                submitFormPF();
            }
        }

    });

    $("#submitBtnPJ").click(function () {
        var recaptchaResponse = $("#hiddenRecaptcha_pj").val();
        if (recaptchaResponse === "") {
            $("<p class='error-message'>Por favor, marque o ReCaptcha.</p>").insertAfter(".recaptcha");
        } else { 
            submitFormPJ();
        }

    });
});

function nextTab(elem) {
    $(elem).next().find('a[data-toggle="tab"]').click();
}
function prevTab(elem) {
    $(elem).prev().find('a[data-toggle="tab"]').click();
}


$('.nav-tabs').on('click', 'li', function() {
    $('.nav-tabs li.active').removeClass('active');
    $(this).addClass('active');
});

function submitFormPF() {
    var apiRUL = window.location.origin.toString() + "/api/servicos/corretor/solicitar-saude-pf";

    let internalEmail = $("#internalEmailId").val();
    let nomeCompleto = $("#nomeCompletoPF").val();
    let tipoDeCredenciamento = $("#tipoDeCredenciamento").val();
    let dataDeNascimento = $("#dataDeNascimentoPF").val();
    let cpf = $("#cpf").val();
    let rg = $("#rg").val();
    let cep = $("#cepPF").val();
    let enderecoResidencial = $("#enderecoResidencial").val();
    let numero = $("#numeroPF").val();
    let complemento = $("#complementoPF").val();
    let bairro = $("#bairroPF").val();
    let estado = $("#estadoPF").val();
    let cidade = $("#cidadePF").val();
    let telefone = $("#telefonePF").val();
    let celular = $("#celularPF").val();   
    let email = $("#email").val();
    let conselho = $("#conselhoPF").val();
    let anoDeFormacao = $("#anoDeFormacao").val();
    let formacaoComplementar = $("#formacaoComplementarPF").val();
