    let tabelaDinamica = $("#tabelaDinamicaPF").val();
    let groupId = window.__SITE__.codigo;
    let userId = '';
    let companyId = '';

    let selectedValues = [];

    $('.checkboxPF:checked').each(function() {
        selectedValues.push($(this).val());
    });

    let especialidades = selectedValues.join('; ');

    var data = "{" +
        "\"nomeCompleto\":" + "\"" + nomeCompleto + "\""+ "," +
