// reCAPTCHA ativo. Mudar para false apenas para desativar temporariamente.
const RECAPTCHA_ENABLED = true;
const RECAPTCHA_SITE_KEY = "6LdfSBgqAAAAANvkuZbuE0JSpQkQkSuels0GYK01";

var recaptchaWidgetId = null;
var recaptchaTentativas = 0;

function loadRecaptchaApi() {
    if (typeof grecaptcha !== "undefined") return;
    if (document.querySelector('script[src*="recaptcha/api.js"]')) return;

    var script = document.createElement("script");
    script.src = "https://www.google.com/recaptcha/api.js?render=explicit&hl=pt-BR";
    script.async = true;
    script.defer = true;
    document.head.appendChild(script);
}

function renderRecaptcha() {
    if (!RECAPTCHA_ENABLED || recaptchaWidgetId !== null) return;

    var container = document.getElementById("recaptchaTEA");
    if (!container) return;

    // Espera o api.js terminar de carregar (até ~15s)
    if (typeof grecaptcha === "undefined" || typeof grecaptcha.render !== "function") {
        if (recaptchaTentativas++ < 60) {
            setTimeout(renderRecaptcha, 250);
        } else {
            console.error("reCAPTCHA: api.js não carregou (bloqueio de rede, CSP ou adblock?).");
        }
        return;
    }

    try {
        recaptchaWidgetId = grecaptcha.render(container, {
            sitekey: container.getAttribute("data-sitekey") || RECAPTCHA_SITE_KEY,
            callback: function () {
                $(".error-message-captcha").hide();
            }
        });
    } catch (e) {
        console.error("reCAPTCHA: falha ao renderizar o widget.", e);
    }
}

function getCaptchaResponse() {
    if (recaptchaWidgetId === null || typeof grecaptcha === "undefined") return "";
    try {
        return grecaptcha.getResponse(recaptchaWidgetId) || "";
    } catch (e) {
        return "";
    }
}

// ------------step-wizard-------------

$(document).ready(function () {
    if (!RECAPTCHA_ENABLED) {
        $(".recaptcha-container").hide();
        $(".error-message-captcha").hide();
    } else {
        loadRecaptchaApi();
        renderRecaptcha();
    }

    $("#carteiraPaciente").val("");
    $("#cpfTitular").mask("000.000.000-00");
    $("#cpfPaciente").mask("000.000.000-00");
    $("#cep").mask("00000-000");
    // Aceita fixo (8 dígitos) e celular (9 dígitos)
    var telefoneMask = function (val) {
        return val.replace(/\D/g, "").length === 11 ? "(00) 00000-0000" : "(00) 0000-00009";
    };
    var telefoneOptions = {
        onKeyPress: function (val, e, field, options) {
            field.mask(telefoneMask.apply({}, arguments), options);
        }
    };
    $("#telefone").mask(telefoneMask, telefoneOptions);
    $("#celular").mask(telefoneMask, telefoneOptions);
    $("#dataNascimentoTitular").mask("00/00/0000");
    $("#dataNascimentoPaciente").mask("00/00/0000");

    $("input[name='Perfil']").change(function () {
        $(".step1").toggleClass("hide");
        $(".step2").toggleClass("hide");
    });

    $(".nav-tabs > li a[title]").tooltip();

    // Wizard
    $('a[data-toggle="tab"]').on("shown.bs.tab", function (e) {
        var target = $(e.target);
        if (target.parent().hasClass("disabled")) {
            return false;
        }
    });

    $(".next-step").click(function () {
        var active = $(".wizard .nav-tabs li.active");
        var currStep = active.children().attr("aria-controls");
        var isValid = false;

        if (currStep === "step1") {
            isValid = validateStep1();
            if (isValid) {
                $(".prev-step").css("opacity", 1);
            }
        }

        if (currStep === "step2") {
            isValid = validateStep2();
        }

        if (isValid) {
            active.next().removeClass("disabled");
            nextTab(active);
            renderRecaptcha(); // garante o widget ao chegar no passo 2
            scrollIntoViewAdjusted($("#formDuvida").get(0), 100);
        }
    });

    $("input[name='primeiroAtendimento']").change(function () {
        var valorSelecionado = $("input[name='primeiroAtendimento']:checked").val();
        if (valorSelecionado === "Nao") {
            $("#msg_sem_primeiro_atendimento").show();
        } else {
            $("#msg_sem_primeiro_atendimento").hide();
        }
    });

    $("input[name='possuiLaudo']").change(function () {
        var valorSelecionado = $("input[name='possuiLaudo']:checked").val();
        if (valorSelecionado === "Nao") {
            $("#msg_sem_laudo").show();
        } else {
            $("#msg_sem_laudo").hide();
        }
    });

    $("#cxSelectRegiao").change(function () {
        var valorSelecionado = ($("#cxSelectRegiao").val() || "").toLowerCase();
        if (valorSelecionado === "outros") {
            $("#msg_sem_regiao").show();
        } else {
            $("#msg_sem_regiao").hide();
        }
    });

    $(".prev-step").click(function () {
        var active = $(".wizard .nav-tabs li.active");
        prevTab(active);
    });

    $(".enviarBtn #submitBtn").click(function () {
        if (validateStep2()) {
            submitForm();
        }
    });
});

function nextTab(elem) {
    $(elem).next().find('a[data-toggle="tab"]').click();
}

function prevTab(elem) {
    $(elem).prev().find('a[data-toggle="tab"]').click();
}

$(".nav-tabs").on("click", "li", function () {
    $(".nav-tabs li.active").removeClass("active");
    $(this).addClass("active");
});

function scrollIntoViewAdjusted(elem, offset = 0) {
    try {
        if (!elem) return;
        window.scrollBy({
            top: elem.getBoundingClientRect().top - offset,
            behavior: "smooth"
        });
    } catch (error) {
        // ignora
    }
}

function submitForm() {
    const arquivoInput = document.getElementById("arquivo");
    const arquivo = arquivoInput.files[0];

    if (!arquivo) {
        alert("Selecione um arquivo antes de enviar!");
        return;
    }

    showLoad();

    const reader = new FileReader();
    reader.onloadend = function () {
        const arquivoBase64 = reader.result.split(",")[1];

        const dados = {
            arquivoBase64: arquivoBase64,
            nomeArquivo: arquivo.name,
            tipoArquivo: arquivo.type
        };

        sendData(dados);
    };
    reader.onerror = function () {
        hideLoad();
        alert("Não foi possível ler o arquivo. Tente novamente.");
    };
    reader.readAsDataURL(arquivo);
    return false;
}

function sendData(objFile) {
    var apiURL =
        window.location.origin.toString() +
        "/api/servicos/email/v2/enviar-email-e-gravar-em-lista-dinamica";

    var regiao = $("#cxSelectRegiao").val();

    // JSON.stringify escapa aspas, quebras de linha etc. digitadas pelo usuário
    var payload = {
        nomeCompletoTitular: $("#nomeCompletoTitular").val(),
        dataNascimentoTitular: $("#dataNascimentoTitular").val(),
        cpfTitular: $("#cpfTitular").val(),
        nomeCompletoPaciente: $("#nomeCompletoPaciente").val(),
        dataNascimentoPaciente: $("#dataNascimentoPaciente").val(),
        cpfPaciente: $("#cpfPaciente").val(),
        telefone: $("#telefone").val(),
        email: $("#email").val(),
        carteiraPaciente: $("#carteiraPaciente").val(),
        primeiroAtendimento: $("input[name='primeiroAtendimento']:checked").val(),
        possuiLaudo: $("input[name='possuiLaudo']:checked").val(),
        cid: $("#cid").val(),
        regiao: regiao,
        regiaoAtuacao: regiao,
        observacao: $("#observacao").val(),
        // Os campos abaixo não podem ser retirados sob quaisquer hipóteses
        tabelaDinamica: $("#tabelaDinamica").val(),
        groupId: String(window.__SITE__.codigo),
        userId: String(''),
        companyId: String(''),
        internalEmail: $("#internalEmail").val(),
        arquivo: objFile
    };

    $.ajax(apiURL, {
        method: "POST",
        contentType: "application/json",
        data: JSON.stringify(payload),

        success: function (data) {
            hideLoad();
            if (data && data.success) {
                $(".msgSucesso").css({ display: "flex" });
                $("#formDuvida").hide();
                scrollIntoViewAdjusted($(".msgSucesso").get(0), 200);
            } else {
                alert("Não foi possível enviar sua solicitação. Tente novamente.");
                resetCaptcha();
            }
        },
        error: function () {
            hideLoad();
            alert("Ocorreu um erro ao enviar sua solicitação. Tente novamente.");
            resetCaptcha();
        }
    });
}

function resetCaptcha() {
    if (!RECAPTCHA_ENABLED) {
        return;
    }

    try {
        if (typeof grecaptcha !== "undefined" && recaptchaWidgetId !== null) {
            grecaptcha.reset(recaptchaWidgetId);
        }
    } catch (e) {
        // ignora
    }
}

function validateField(selector) {
    removeError(selector);
    if ($(selector).val() == undefined || $(selector).val().trim() === "") {
        $("<p class='error-message'>*Campo obrigatório</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }
    return true;
}

function validateFieldCheck(selector, selectMsg) {
    $(selectMsg).hide();
    if ($(selector).val() == undefined || $(selector).val().trim() == "") {
        $(selectMsg).show();
        return false;
    }
    return true;
}

function validateStep1() {
    var isValid = true;

    isValid &= validateField("#nomeCompletoTitular");
    isValid &= validateField("#dataNascimentoTitular");
    isValid &= validateField("#cpfTitular");
    isValid &= validateField("#nomeCompletoPaciente");
    isValid &= validateField("#dataNascimentoPaciente");
    isValid &= validateField("#cpfPaciente");
    isValid &= validateField("#carteiraPaciente");
    isValid &= validateField("#telefone");
    isValid &= validateField("#email");
    isValid &= validarEmail("#email");
    isValid &= validarDataMenorQueHoje("#dataNascimentoTitular");
    isValid &= validarDataMenorQueHoje("#dataNascimentoPaciente");
    isValid &= validarCPF("#cpfTitular");
    isValid &= validarCPF("#cpfPaciente");

    if (!isValid) {
        scrollIntoViewAdjusted($(".error-message")[0], 200);
    }

    return !!isValid;
}

function validateStep2() {
    var isValid = true;

    // validação do captcha (só quando estiver ativo)
    $(".error-message-captcha").hide();
    if (RECAPTCHA_ENABLED) {
        if (getCaptchaResponse() === "") {
            isValid = false;
            $(".error-message-captcha").show();
        }
    }

    if ($(".msgAtencao:visible").length) {
        scrollIntoViewAdjusted($("#formDuvida").get(0), 100);
        return false;
    }

    isValid &= validateFieldCheck("input[name='primeiroAtendimento']:checked", "#errorMessage_primeiroAtendimento");
    isValid &= validateFieldCheck("input[name='possuiLaudo']:checked", "#errorMessage_possuiLaudo");
    isValid &= validateField("#cid");

    // Validação do select de região
    var regionValue = $("#cxSelectRegiao").val();
    $("#cxSelectRegiao").removeClass("error-border");
    $(".error-message-regiao").remove();

    if (regionValue === "" || regionValue === null) {
        $("<p class='error-message error-message-regiao'>*Selecione uma Região</p>").insertBefore("#cxSelectRegiao");
        $("#cxSelectRegiao").addClass("error-border");
        isValid = false;
    }

    // Observação: opcional, mas se preenchida precisa de no mínimo 10 caracteres
    var obs = ($("#observacao").val() || "").trim();
    if (obs.length > 0 && obs.length < 10) {
        $("#errorMessage").show();
        isValid = false;
    }

    return !!isValid;
}

function showLoad() {
    $("#loadingDiv").show();
}

function hideLoad() {
    $("#loadingDiv").hide();
}

function removeError(selector) {
    $(selector).prevAll(".error-message").remove();
    $(selector).removeClass("error-border");
}

function validarEmail(selector) {
    var email = ($(selector).val() || "").trim();
    if (email === "") return false; // já tratado em validateField
    var regexEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!regexEmail.test(email)) {
        removeError(selector);
        $("<p class='error-message'>*Informe um e-mail válido.</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }
    return true;
}

function validarDataMenorQueHoje(selector) {
    const data = $(selector).val() || "";
    const regexData = /^(\d{2})\/(\d{2})\/(\d{4})$/;
    const match = data.match(regexData);

    if (!match) {
        removeError(selector);
        $("<p class='error-message'>*Informe a data no padrão DD/MM/AAAA</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    const dia = parseInt(match[1], 10);
    const mes = parseInt(match[2], 10) - 1;
    const ano = parseInt(match[3], 10);

    const dataInserida = new Date(ano, mes, dia);

    // Garante que a data existe (ex.: 31/02 é inválido)
    if (
        dataInserida.getFullYear() !== ano ||
        dataInserida.getMonth() !== mes ||
        dataInserida.getDate() !== dia
    ) {
        removeError(selector);
        $("<p class='error-message'>*Data inválida.</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    const dataAtual = new Date();
    dataAtual.setHours(0, 0, 0, 0);
    removeError(selector);

    if (dataInserida < dataAtual) {
        return true;
    } else {
        $("<p class='error-message'>*A data de nascimento deve ser menor que hoje.</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }
}

function validarCPF(selector) {
    let cpf = $(selector).val() || "";
    cpf = cpf.replace(/[^\d]/g, "");

    if (cpf.length !== 11) {
        removeError(selector);
        $("<p class='error-message'>*CPF deve ter 11 dígitos.</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    if (/^(\d)\1+$/.test(cpf)) {
        removeError(selector);
        $("<p class='error-message'>*CPF inválido (todos os dígitos iguais).</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    let soma = 0;
    for (let i = 0; i < 9; i++) {
        soma += parseInt(cpf.charAt(i)) * (10 - i);
    }
    let primeiroDigitoVerificador = 11 - (soma % 11);
    if (primeiroDigitoVerificador >= 10) {
        primeiroDigitoVerificador = 0;
    }

    if (primeiroDigitoVerificador != cpf.charAt(9)) {
        removeError(selector);
        $("<p class='error-message'>*CPF inválido</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    soma = 0;
    for (let i = 0; i < 10; i++) {
        soma += parseInt(cpf.charAt(i)) * (11 - i);
    }
    let segundoDigitoVerificador = 11 - (soma % 11);
    if (segundoDigitoVerificador >= 10) {
        segundoDigitoVerificador = 0;
    }

    if (segundoDigitoVerificador != cpf.charAt(10)) {
        removeError(selector);
        $("<p class='error-message'>*CPF inválido</p>").insertBefore(selector);
        $(selector).addClass("error-border").focus();
        return false;
    }

    return true;
};

