$(document).ready(function () {
    function aplicarSelect2() {
        if (typeof $.fn.select2 === "function") {
            $('#lpCirurgias').select2({
                placeholder: 'Pesquise aqui',
                allowClear: true,
                language: {
                    noResults: function() {
                        return "Nenhum resultado encontrado";
                    }
                },
                sorter: function(data) {
                    return data.sort(function(a, b) {
                        if (a.text === "Pesquise aqui") return -1;
                        if (b.text === "Pesquise aqui") return 1;
                        return a.text.localeCompare(b.text);
                    });
                },
                matcher: function(params, data) {
                    if ($.trim(params.term) === '') {
                        return data;
                    }
                    let termoPesquisa = params.term.toLowerCase();
                    let tituloCirurgia = data.text.toLowerCase();
                    let sinonimias = $(data.element).data('sinonimias');

                    if ($(data.element).is(':disabled')) {
                        return null;
                    }

                    if (tituloCirurgia.includes(termoPesquisa)) {
                        return data;
                    }

                    if (sinonimias) {
                        if (sinonimias.toLowerCase().includes(termoPesquisa.toLowerCase())) {
                            return $.extend({}, data, true);
                        }
                    }

                    return null;
                }
            });

            $('#lpCirurgias').on('change', function () {
                var selectedValue = $(this).val();
                if (selectedValue) {
                    window.location.href = selectedValue;
                }
            });
        } else {
            console.warn("Plugin select2 ainda não carregado, tentando novamente...");
            setTimeout(aplicarSelect2, 200);
        }
    }

    window.addEventListener("load", function () {
        aplicarSelect2();
    });

    // Inicializa o Swiper após o carregamento completo
    function inicializarSwiper() {
        if (typeof Swiper !== 'undefined') {
            var sliderCategoriaLP = document.querySelector(".sliderCategoriaLP");
            if (sliderCategoriaLP) {
                var swiper = new Swiper(sliderCategoriaLP, {
                    spaceBetween: 15,
                    slidesPerView: 3,
                    navigation: {
                        nextEl: ".btnNextFiltercateg",
                        prevEl: ".btnPrevFiltercateg",
                    },
                    breakpoints: {
                        360: {
                            slidesPerView: 2.2,
                        },
                        500: {
                            slidesPerView: 1.3,
                        },
                        768: {
                            slidesPerView: 1.8,
                        },
                        1200: {
                            slidesPerView: 3,
                        },
                    },
                });
            }
        } else {
            console.warn("Swiper ainda não carregado, tentando novamente...");
            setTimeout(inicializarSwiper, 200);
        }
    }

    // Aguarda o carregamento completo antes de inicializar o Swiper
    window.addEventListener("load", function () {
        setTimeout(inicializarSwiper, 100);
    });
});;

