// Variáveis globais para paginação
let dadosAtualBusca = null;
let termoAtualBusca = '';
let paginaAtual = 1;
const itensPorPagina = 10;

// Função para atualizar a paginação
function atualizarPaginacao(totalPaginas, paginaAtual) {
    const paginacao = document.querySelector('.vertex_pagination');

    if (!paginacao || totalPaginas <= 1) {
        paginacao.style.display = 'none';
        return;
    }

    paginacao.style.display = 'flex';

    // Limpar paginação atual
    paginacao.innerHTML = '';

    // Botão Anterior
    const btnAnterior = document.createElement('a');
    btnAnterior.className = 'vertex_prev';
    btnAnterior.href = '#';
    btnAnterior.innerHTML = `
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20">
            <rect width="20" height="20" fill="none"/>
            <path d="M12 5 L6 10 L12 15" fill="none" stroke="#707070" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5"/>
        </svg>
        Anterior
    `;

    if (paginaAtual <= 1) {
        btnAnterior.style.display = 'none';
    } else {
        btnAnterior.onclick = (e) => {
            e.preventDefault();
            realizarBusca(paginaAtual - 1);
        };
    }

    paginacao.appendChild(btnAnterior);

    // Números das páginas
    const maxPaginasVisiveis = 5;
    let inicioRange = Math.max(1, paginaAtual - Math.floor(maxPaginasVisiveis / 2));
    let fimRange = Math.min(totalPaginas, inicioRange + maxPaginasVisiveis - 1);

    // Ajustar range se estiver no final
    if (fimRange - inicioRange + 1 < maxPaginasVisiveis) {
        inicioRange = Math.max(1, fimRange - maxPaginasVisiveis + 1);
    }

    // Primeira página se não estiver no range
    if (inicioRange > 1) {
        const primeira = criarBotaoPagina(1, paginaAtual);
        paginacao.appendChild(primeira);

        if (inicioRange > 2) {
            const reticencias = document.createElement('span');
            reticencias.textContent = '...';
            reticencias.style.padding = '0 10px';
            paginacao.appendChild(reticencias);
        }
    }

    // Páginas do range
    for (let i = inicioRange; i <= fimRange; i++) {
        const botaoPagina = criarBotaoPagina(i, paginaAtual);
        paginacao.appendChild(botaoPagina);
    }

    // Última página se não estiver no range
    if (fimRange < totalPaginas) {
        if (fimRange < totalPaginas - 1) {
            const reticencias = document.createElement('span');
            reticencias.textContent = '...';
            reticencias.style.padding = '0 10px';
            paginacao.appendChild(reticencias);
        }

        const ultima = criarBotaoPagina(totalPaginas, paginaAtual);
        paginacao.appendChild(ultima);
    }

    // Botão Próximo
    const btnProximo = document.createElement('a');
    btnProximo.className = 'vertex_next';
    btnProximo.href = '#';
    btnProximo.innerHTML = `Próximo
        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20">
            <g id="para_baixo" data-name="para baixo" transform="translate(0 20) rotate(-90)">
                <rect id="Rectangle_356" data-name="Rectangle 356" width="20" height="20" fill="none"/>
                <path id="Path_382" data-name="Path 382" d="M158.476,424.278l6.737-7,6.263,7" transform="translate(174.976 430.778) rotate(180)" fill="none" stroke="#707070" stroke-linecap="round" stroke-linejoin="round" stroke-width="1.5"/>
            </g>
        </svg>
    `;

    if (paginaAtual >= totalPaginas) {
        btnProximo.style.display = 'none';
    } else {
        btnProximo.onclick = (e) => {
            e.preventDefault();
            realizarBusca(paginaAtual + 1);
        };
    }

    paginacao.appendChild(btnProximo);
}

// Função para criar botão de página
function criarBotaoPagina(numeroPagina, paginaAtual) {
    const botao = document.createElement('div');
    botao.className = 'vertex_pagination_number text-center';
    botao.textContent = numeroPagina;
    botao.tabIndex = 0;

    if (numeroPagina === paginaAtual) {
        botao.classList.add('active');
    } else {
        botao.style.cursor = 'pointer';
        botao.onclick = () => realizarBusca(numeroPagina);
        botao.onkeypress = (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                realizarBusca(numeroPagina);
            }
        };
    }

    return botao;
}

// Função para realizar a busca
async function realizarBusca(pagina = 1) {
    let termoBusca;

    if (pagina === 1) {
        // Nova busca
        termoBusca = document.getElementById('cxpesquisar').value.trim();

        if (!termoBusca) {
            alert('Por favor, digite um termo para buscar.');
            return;
        }
    } else {
        // Paginação - usar termo atual
        termoBusca = termoAtualBusca;
    }

    // Verificar reCAPTCHA antes de realizar a busca
    try {

        // Mostrar loading
        mostrarLoading();

        const currentURL = window.location.href;

            const regioesMap = {
            "sao-paulo": { nome: "São Paulo", uf: "SP" },
            "minas-gerais": { nome: "Minas Gerais", uf: "MG" },
            };

            for (const slug in regioesMap) {
            if (currentURL.includes(slug)) {
                regiaoNome = regioesMap[slug].nome;
                regiaoUf = regioesMap[slug].uf;
                break;
            }
            }
        // Calcular offset para paginação
        const offset = (pagina - 1) * itensPorPagina;
          //'g-recaptcha-response': recaptchaToken
        const response = await fetch('/api/servicos/searchCirurgia/search', {
            method: 'POST',
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'    
            },
            body: JSON.stringify({
                "query": termoBusca,
                "pageSize": itensPorPagina,
                "offset": offset,
                "queryExpansionSpec": {
                    "condition": "AUTO"
                },
                "spellCorrectionSpec": {
                    "mode": "AUTO"
                },
                "languageCode": "en-US",
                "filter": "estado: ANY(\"" + regiaoUf + "\")",
                "facetSpecs": [
                    {
                        "facetKey": {
                            "key": "estado"
                        },
                        "limit": 30
                    }
                ]
            })
        });

        if (!response.ok) {
            if (response.status === 403) {
                alert('Verificação de segurança falhou. Você pode ser um robô.');
                return;
            }
            throw new Error('Erro na requisição: ' + response.status);
        }

        const data = await response.json();
        exibirResultados(data, termoBusca, pagina);

    } catch (error) {
        console.error('Erro ao buscar:', error);
        if (error.message.includes('recaptcha')) {
            alert('Erro na verificação de segurança. Recarregue a página e tente novamente.');
        } else {
            alert('Erro ao realizar a busca. Tente novamente.');
        }
    } finally {
        esconderLoading();
    }
}

// Função para exibir os resultados
function exibirResultados(data, termoBusca, pagina = 1) {
    // Armazenar dados para paginação
    dadosAtualBusca = data;
    termoAtualBusca = termoBusca;
    paginaAtual = pagina;

    const container = document.querySelector('.vertex-container');
    const resultadosDiv = container.querySelector('.vertex_resultados');

    // Atualizar campo de resultado
    const cxResultado = document.getElementById('cxResultado');
    if (cxResultado) {
        cxResultado.value = termoBusca;
    }

    // Calcular informações de paginação
    const total = data.totalSize || 0;
    const totalPaginas = Math.ceil(total / itensPorPagina);
    const inicioItem = ((pagina - 1) * itensPorPagina) + 1;
    const fimItem = Math.min(pagina * itensPorPagina, total);

    // Atualizar total de resultados
    const totalResultados = container.querySelector('.totalResultados');
     const paginacao = document.querySelector('.vertex_pagination');
    if (totalResultados) {
        if (total > 0) {
            totalResultados.innerHTML = `Mostrando ${fimItem} de ${total} para <span class="nomeDePesquisa">${termoBusca}</span>`;
              paginacao.style.display = 'flex';
        } else {
            totalResultados.innerHTML = `Nenhum resultado encontrado para <span class="nomeDePesquisa">${termoBusca}</span>`;
               paginacao.style.display = 'none';
        }
    }

    // Limpar resultados anteriores
    const itensAntigos = container.querySelectorAll('.vertex_text_item');
    itensAntigos.forEach(item => item.remove());

    // Adicionar novos resultados
    if (data.results && data.results.length > 0) {
        const fragment = document.createDocumentFragment();

        data.results.forEach(result => {
            const structData = result.document.structData;

            const itemDiv = document.createElement('div');
            itemDiv.className = 'vertex_text_item mb-4';

            itemDiv.innerHTML = `
                ${structData.link_portal ? `<a href="${structData.link_portal}" title="Acesse ${structData.nome_opular}">
                <h3 tabindex="0">${structData.nome_opular || structData.nome_cirurgia || 'Cirurgia'}</h3>
                <p tabindex="0">${structData.categoria || 'Categoria não informada'}</p>
                <p tabindex="0">${structData.descricao_curta || structData.desc_curta || structData.descricao_completa || structData.desc_longa || 'Descrição não disponível'}</p>
               </a>` : ''}
            `;

            fragment.appendChild(itemDiv);
        });

        // Inserir antes da paginação
        const paginacao = container.querySelector('.vertex_pagination');
        paginacao.parentNode.insertBefore(fragment, paginacao);
    } else {
        // Nenhum resultado encontrado
        const semResultado = document.createElement('div');
        semResultado.className = 'vertex_text_item mb-4';
        semResultado.innerHTML = `
            <h3 tabindex="0">Nenhum resultado encontrado</h3>
            <p tabindex="0">Tente usar outros termos de busca.</p>
        `;

        const paginacao = container.querySelector('.vertex_pagination');
        paginacao.parentNode.insertBefore(semResultado, paginacao);
    }

    // Atualizar paginação
    atualizarPaginacao(totalPaginas, pagina);

    // Mostrar container de forma sobreposta
    mostrarContainer();
}

// Função para mostrar o container de resultados
function mostrarContainer() {
    const container = document.querySelector('.vertex-container');

    // Adicionar estilos para sobreposição
    container.style.position = 'fixed';
    container.style.top = '0';
    container.style.left = '0';
    container.style.width = '100%';
    container.style.height = '100%';
    container.style.backgroundColor = 'rgba(255, 255, 255, 0.95)';
    container.style.zIndex = '9999';
    container.style.padding = '20px';
    container.style.overflowY = 'auto';
    container.style.display = 'block';

    // Adicionar botão de fechar
    let btnFechar = container.querySelector('.btn-fechar-resultados');
    if (!btnFechar) {
        btnFechar = document.createElement('button');
        btnFechar.className = 'btn-fechar-resultados';
        btnFechar.innerHTML = '✕';
        btnFechar.style.cssText = `
            position: absolute;
            top: 20px;
            right: 20px;
            background: #0435AC;
            color: white;
            border: none;
            border-radius: 50%;
            width: 40px;
            height: 40px;
            font-size: 20px;
            cursor: pointer;
            z-index: 10000;
        `;

        btnFechar.onclick = fecharContainer;
        container.insertBefore(btnFechar, container.firstChild);
    }
}

// Função para fechar o container
function fecharContainer() {
    const container = document.querySelector('.vertex-container');
    container.style.display = 'none';
    container.style.position = 'static';
    container.style.backgroundColor = 'transparent';
    container.style.zIndex = 'auto';
    container.style.padding = '0';
    container.style.overflowY = 'visible';
}

// Função para mostrar loading
function mostrarLoading() {
    const lupa = document.querySelector('.vertex_lupa');
    lupa.innerHTML = `
        <div style="width: 16px; height: 16px; border: 2px solid #fff; border-top: 2px solid transparent; border-radius: 50%; animation: spin 1s linear infinite;"></div>
        <style>
            @keyframes spin {
                0% { transform: rotate(0deg); }
                100% { transform: rotate(360deg); }
            }
        </style>
    `;
}

// Função para esconder loading
function esconderLoading() {
    const lupa = document.querySelector('.vertex_lupa');
    lupa.innerHTML = `
        <svg xmlns="http://www.w3.org/2000/svg" width="16.704" height="16.714" viewBox="0 0 16.704 16.714">
            <path id="Path_11825" data-name="Path 11825"
                d="M15.247,13.778h-.774l-.274-.265a6.387,6.387,0,1,0-.686.686l.265.274v.774l4.164,4.164a1.032,1.032,0,0,0,1.46-1.46Zm-5.879,0a4.409,4.409,0,1,1,4.409-4.409A4.4,4.4,0,0,1,9.369,13.778Z"
                transform="translate(-2.999 -2.999)" fill="#fff" />
        </svg>
    `;
}

// Event listeners
document.addEventListener('DOMContentLoaded', function() {
    const inputBusca = document.getElementById('cxpesquisar');
    const btnLupa = document.querySelector('.vertex_lupa');
    const container = document.querySelector('.vertex-container');

    // Esconder container inicialmente
    container.style.display = 'none';



    // Evento de clique no botão de busca
    if (btnLupa) {
        btnLupa.addEventListener('click', () => realizarBusca(1));
        btnLupa.addEventListener('keypress', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
                realizarBusca(1);
            }
        });
    }

    // Evento de Enter no campo de busca
    if (inputBusca) {
        inputBusca.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                realizarBusca(1);
            }
        });
    }
});;

