    $("#submitBtn").click(function (e) {
        e.preventDefault(); // Impede o comportamento padrão do botão
        if (validateStep6()) { // Verifica se a validação passou
            sendData(); // Só envia os dados se a validação for verdadeira
        } else {
            //console.log("Validação falhou!"); // Para depuração
        }
