        //console.log('Entrou na função sendDataSalesForce enviando tudo.')
			$(".boxBtnForm").hide();  
        const form = document.getElementById("formVD");
        const filledFormData = new FormData(form);

        var apiURL =
        window.location.origin.toString() +
        "/api/servicos/generico/enviarSalesforce";

            //console.log(apiURL)
            let url = window.location.href;
            let cxNomeCompleto = $("#cxNomeCompleto").val();
            let cxtel = $("#tel").val();
            let cxcpf = $("#cxNumCPF").val();
            let cxemail = $("#cxemail").val();
            let ufOrigem = carregarUFOrigem();
            let cxselectUF = $("#selectUF").val();
            let cxselectCidade = $('#selectCidade option:selected').text();
            let cxcirurgiaInte = $("#cirurgiaInte").val();
            let cxExtra = $("#cxExtra").val();
            let preFixoAssuntoEmail = $("#preFixoAssuntoEmail").val();
            let internalEmail = $("#internalEmail").val();
            let groupId = window.__SITE__.codigo;
            let userId = '';
            let companyId = '';
            let pageTitle = document.title;
            pageTitle = pageTitle.split(" - ")[0]  
            let subject = preFixoAssuntoEmail + " " + pageTitle;

            const template = `
            <body>
            <div>
            <p><strong>Prezado (a): Responsável NDI</strong></p>
            <p>Segue a solicitação para ser um Corretor conforme informações abaixo:</p>
            ${
                [...filledFormData].map(([key, value]) => {
                    const inputElement = form.querySelector(`[name="${key}"]`);
                    const labelElement = form.querySelector(`label[for="${inputElement.id}"]`);
                    const labelText = labelElement ? labelElement.textContent : null;

                    const displayValue = inputElement.tagName === "SELECT" 
                    ? inputElement.selectedOptions[0]?.text 
                    : value;

                    return displayValue !== "" && labelText != null 
                    ? `<p>${labelText}: ${displayValue}</p>` 
                    : '';
                }).join('') 
            }
            <p>Cirurgia: ${cxcirurgiaInte}</p
            <p>Atenciosamente,</p>
            <p>${cxNomeCompleto}</p>
            <p>${cxtel}</p>
            <p>URL Página: ${window.location.href}</p>
            </div>
            </body>
            `;

            const cleanTemplate = template.replace(/\n/g, "").replace(/\s{2,}/g, " ");

            const data =
            {
                url : url,
                nomeCompleto: cxNomeCompleto,
                telefone: cxtel,              
                emailTo: cxemail,
                cpf: cxcpf,
                ufOrigem: ufOrigem,
                uf: cxselectUF,  
                cidade: cxselectCidade,
                cirurgiaInteresse: cxcirurgiaInte,
                campoExtraProcedimento: cxExtra,                               
                groupId: groupId,
                userId: userId,
                companyId: companyId,
                internalEmail: internalEmail,
                template: cleanTemplate,
                subject: subject     
            };

            try {
                const response = await fetch(apiURL, {
                    method: "POST",
                    headers: {
                        "Content-Type":  "application/json"
                    },
                    body: JSON.stringify(data)
                });
                //console.log("Payload enviado:", JSON.stringify(data));
                const result = await response.json();
            } catch (error) {
                console.log("Erro ao enviar e-mail: " + error.message);
            }
    }

