    /*==================Validações de campos=========================*/


    // Avançar para o próximo passo com validação
    $(".next").on("click keydown", function (e) {
        if (e.type === "click" || (e.type === "keydown" && e.key === "Enter")) {
            const currentStep = $(".formCirurgiaEtapas .tab-pane.active").attr("id");

            // Valida os campos da etapa atual
            if (validateStep(currentStep)) {
                // Verifica se estamos no passo 2 ou posterior para chamar o endpoint Salesforce
                if (configuration.tipoDeExibicao === "parcial" 
                    &&(currentStep === "step2" 
                    ||currentStep === "step3" 
                    ||currentStep === "step4"
                    ||currentStep === "step5")) {
                    enviarDadosSalesforce();
                    } 

