$(document).ready(function () {	
    $("#successSendMessage").hide();
	  $("#erroSendMessage").hide();
    $('#cxtelefone').mask('(00) 0000-00000');
	  var numeroCaracteres = 0;	
	  var textarea = document.getElementById('tMensagem');
    var contadorCaracteres = document.getElementById('contador-caracteres');

    textarea.addEventListener('input', function() {
      var numeroCaracteres = textarea.value.length;
			var textoCaractere = (numeroCaracteres === 1) ? 'caractere' : 'caracteres';
      contadorCaracteres.textContent = numeroCaracteres + ' ' + textoCaractere + ' (MIN.10/MÁX.4000)';
    });
    var apiErrors = [];

    //formulario
    $('#submitBtn').click(function () {
        $(".error-message").remove();
        $(".form-control").removeClass("error-border");
        validateForm();

        //checa erro e envia form
        if ($(".error-message").length === 0) {
					    $('#submitBtn').prop('disabled', true);
              submitForm();
        }
    });

    function submitForm() {

		var apiURL = window.location.origin.toString() + "/api/servicos/hapvida/open/send-fale-conosco-message";

        //recupera valores dos campos
        var motivo = $('#selectMotivo').val();
        var carteirinha = $('#codCarteirinha').val();
        var email = $('#cxemail').val();
        var telefone = $('#cxtelefone').val().replace(/\D/g, '');
        var mensagem = $('#tMensagem').val();

        var data = {
            email: email,
            phoneNumber: telefone,
            cdUser: carteirinha,
            subject: motivo,
            description: mensagem,
					  ufCode: "-",
					  cityName: "-"
        };
        console.log("data: " + JSON.stringify(data));

        //monta header para requisição 
        var requestOptions = {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(data),
            redirect: 'follow'
        };

        //requisição API
        fetch(apiURL, requestOptions)
            .then(response => {
                if (response.ok) {
									  return response.json();
                } else {
                    return response.text().then(text => {
                        const mensagemErro = text;
                        console.log(mensagemErro);
                        apiErrors.push(mensagemErro);
                    });
								}
            })
            .then(result => {
							contadorCaracteres.textContent = '';

					    $('#submitBtn').prop('disabled', false);
                console.log('Resposta da API:', result);
                if (result !== undefined) {
                    $("#submitFormDiv").hide();
                    $("#successSendMessage").show();

                    var protocolo = result.sacProtocol;
                   $("#protocolo").html("O número do seu Protocolo é <strong>" + protocolo + "</strong>");
                } else {
								    throw new Error('A resposta da API está vazia ou não pode ser processada.');
								}
            })
            .catch(error => {
							contadorCaracteres.textContent = '';
                console.error('Erro na requisição:', error);
                $(".error-message").remove();
                $("#codCarteirinha").removeClass("error-border");
                if (apiErrors.length > 0) {
                    apiErrors.forEach(error => {
                        //valida se carteirinha inserida é valida
                        if (error.includes("carteira")) {
                            $("<p class='error-message'>Número da carteirinha inválido.</p>").insertAfter("#codCarteirinha");
                            $("#codCarteirinha").addClass("error-border");
                        } else if (error.includes("telefone")){
                            $("<p class='error-message'>Número de telefone inválido.</p>").insertAfter("#cxtelefone");
                            $("#cxtelefone").addClass("error-border");
												} else if (error.includes("aguarde")) {
													  $("#submitFormDiv").hide();
														trocarMensagem("Vimos que você acabou de registrar uma demanda, Por gentileza, aguarde 5 minutos para abrir uma nova.");
	                          $("#erroSendMessage").show();	
                        } else {
													  $("#submitFormDiv").hide();
	                          $("#erroSendMessage").show();												}
                    });
                    apiErrors.length = 0;
                }
            });
    }

	  //mensagem de erro
		function trocarMensagem(novaMensagem) {
			var mensagemElement = document.getElementById('mensagem');
			mensagemElement.textContent = novaMensagem;
		}

    //valida campos form
    function validateForm() {

        //valida campo Motivo
        if ($("#selectMotivo").val() === "" || $("#selectMotivo").val() === null) {
            $("<p class='error-message'>Por favor, selecione um motivo.</p>").insertAfter("#selectMotivo");
            $("#selectMotivo").addClass("error-border");
        } else {
            $("#selectMotivo").removeClass("error-border");
        }

        /*//valida campo Carneirinha
        if ($("#codCarteirinha").val() === "") {
            $("<p class='error-message'>Por favor, insira o número da carteirinha.</p>").insertAfter("#codCarteirinha");
            $("#codCarteirinha").addClass("error-border");
        }*/

			var carteirinha = $("#codCarteirinha").val().trim();
				 var apenasNumeros = /^[0-9]{6,}$/; 

        if (carteirinha === "") {
				$("<p class='error-message'>Por favor, insira o número da carteirinha.</p>").insertAfter("#codCarteirinha");
				$("#codCarteirinha").addClass("error-border");
				} else if (!apenasNumeros.test(carteirinha)) {
					$("<p class='error-message'>Número da carteirinha inválido..</p>").insertAfter("#codCarteirinha");
					$("#codCarteirinha").addClass("error-border");
			} else {
					$("#codCarteirinha").removeClass("error-border");
			}



        //valida campo Telefone
        var telefone = $("#cxtelefone").val();
        var telefoneRegex = /^\(\d{2}\)\s*\d{4}-?\d{4,5}$/; 
        console.log("data: " + JSON.stringify(telefone));

        if (telefone.trim() === "") {
            $("<p class='error-message'>Por favor, preencha o campo de telefone/celular.</p>").insertAfter("#cxtelefone");
            $("#cxtelefone").addClass("error-border");
        } else if (!telefoneRegex.test(telefone)) {
            $("<p class='error-message'>Formato de telefone/celular inválido. Por favor, insira no formato (99) 9999-99999.</p>").insertAfter("#cxtelefone");
            $("#cxtelefone").addClass("error-border");
        }

        //valida campo Mensagem
        var mensagem = $("#tMensagem").val();
        if (mensagem.trim() === "") {
            $("<p class='error-message'>Por favor, insira uma mensagem.</p>").insertAfter("#tMensagem");
            $("#tMensagem").addClass("error-border");
        } else if (mensagem.length < 10) {
            $("<p class='error-message'>Comentário curto. Favor detalhar melhor a sua solicitação.</p>").insertAfter("#tMensagem");
            $("#tMensagem").addClass("error-border");
        } else if (mensagem.length > 4000) {
            $("<p class='error-message'>Comentário longo. Favor inserir uma mensagem com até 4.000 caracteres.</p>").insertAfter("#tMensagem");
            $("#tMensagem").addClass("error-border");
        } else {
            $("#tMensagem").removeClass("error-border");
        }

        //valida campo ReCaptcha
        var recaptchaResponse = grecaptcha.getResponse();
        if (recaptchaResponse === "") {
            $("<p class='error-message'>Por favor, marque o ReCaptcha.</p>").insertAfter(".recaptcha");
        } console.log("grec:::::", grecaptcha);
			console.log("recaptchaResponse:::::", recaptchaResponse);			

        //valida campo E-mail
        var email = $("#cxemail").val();
        if (email.trim() === "") {
            $("<p class='error-message'>Por favor, preencha o campo de e-mail.</p>").insertAfter("#cxemail");
            $("#cxemail").addClass("error-border");
        } else if (!isValidEmail(email)) {
            $("<p class='error-message'>E-mail inválido.</p>").insertAfter("#cxemail");
            $("#cxemail").addClass("error-border");
        }
    }

    //valida formato do e-mail
    function isValidEmail(email) {
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }
});

