.topo a:focus-visible,
.topo a:hover {
  border: 2px solid transparent !important;
}
html .contraste-body .pc-main-banner {
  border: 1px solid var(--white);
}
.pc-main-banner {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-height: 396px;
  overflow: hidden;
  position: relative;
}
.pc-main-banner .background-container {
  display: flex;
  width: 100%;
  height: 100%;
  position: absolute;
}
.pc-main-banner .pcimagem {
  display: block;
  margin-left: auto;
  max-width: 700px;
  width: 100%;
  border-radius: 0px 0px 0px 50px;
  overflow: hidden;
}
.pc-main-banner .background-container img.imgFundoPC {
  display: block;
  min-height: 397px;
  height: 100%;
  width: 100%;
}
.pc-main-banner .main-content {
  display: flex;
  flex-direction: column;
  z-index: 3;
	row-gap:30px;
}
.pc-main-banner .main-content .text-container {
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 58%;
  width: 100%;
  min-height: 190px;
  padding: 17px 0;
  border-radius: 6px;
  background-color: #00000066;
	margin-bottom: 30px;
}
.pc-main-banner .main-content .text-container h1.title-content {
  font-family: "oxygen-bold";
  font-size: 32px;
  color: var(--white);
  margin-bottom: 16px;
}

.pc-main-banner .main-content .text-container .text-content {
  color: var(--white);
  font-size: 16px;
  font-family: "oxygen-regular";
  line-height: 26px;
  text-align: left;
}
.pc-main-banner .btnBanner {
  border: 1px solid;
  min-width: 200px;
  max-width: 244px;
  background-color: var(--white);
  border: 1px solid var(--white);
  color: var(--primary);
  font-weight: bold;
  padding: 10px 10px;
  border-radius: 8px;
}
.pc-main-banner .btnBanner:hover {
  border: 1px solid var(--white);
  color: var(--primary);
}

.pc-main-banner .lineLeft,
.lineRight {
  width: 1px;
  background: var(--white);
  display: block;
  position: absolute;
  bottom: 0;
  z-index: 1;
}
.pc-main-banner .containerLineLeft{
	position:absolute;
	bottom:0;
	height: 91%;
	z-index:-1;
}
html .contraste-body .pc-main-banner .lineLeft,
html .contraste-body .pc-main-banner .lineRight {
  background-color: #ff0 !important;
  color: #ff0 !important;
}
.pc-main-banner .lineLeft {
  left: auto;
  height: 45%;
	z-index: -1;
}
.pc-main-banner .lineRight {
  right: 7%;
  height: 100%;
}
.pc-main-banner .banner-small {
  padding-left: 2.125rem;
  padding-right: 10px;
}
.pc-main-banner .banner-medium {
  padding-left: 5.125rem;
  padding-right: 10px;
}
.pc-main-banner .banner-larger {
  padding-left: 9rem;
  padding-right: 10px;
}
.pc-main-banner .banner-huge {
  padding-left: 13rem;
  padding-right: 10px;
}
.pc-main-banner .banner-gigantic {
  padding-left: 16rem;
  padding-right: 10px;
}
.signed-in.has-edit-mode-menu .pc-main-banner {
  margin-top: 0;
}

.pc-main-banner .menuBreadcrumb {
  background-color: transparent;
  font-family: "oxygen-regular";
}

.pc-main-banner .menuBreadcrumb a {
	color: #fff!important;
}
.pc-main-banner .menuBreadcrumb a:hover {
	color: #fff!important;
}
.pc-main-banner .menuBreadcrumb a:last-child {
  font-weight: normal;
}
html .contraste-body .pc-main-banner .menuBreadcrumb a{
color: #ff0 !important;
}

@media screen and (min-width: 1614px) and (max-width: 1920px) {
  .pc-main-banner .main-content .text-container {
    max-width: 73%;
  }
}
@media screen and (min-width: 1920px) {
  .pc-main-banner .main-content .text-container {
    max-width: 80%;
  }
}
@media screen and (max-width: 960px) {
  .pc-main-banner .background-container {
    display: none;
  }
  .pc-main-banner .main-content .text-container {
    background-color: transparent;
    max-width: initial;
  }

  .pc-main-banner .main-content {
		row-gap: 17px;
  }
  .pc-main-banner .lineLeft,
  .lineRight {
    display: none;
  }
	.pc-main-banner .banner-small,
  .pc-main-banner .banner-medium,
  .pc-main-banner .banner-larger,
  .pc-main-banner .banner-huge,
  .pc-main-banner .banner-gigantic {
    padding-left: 0;
    padding-right: 0;
  }
}

@media screen and (max-width: 768px) {
  .pc-main-banner {
    margin-top: 175px;
  }
  .pc-main-banner .main-content .text-container h1.title-content {
    font-size: 1.5rem;
  }

}

