.fragment-cards-carousel .custom-card {
    background-color: #fff;
    border-radius: 3px;
    box-shadow: 4px 4px 16px #00000029;
    min-height: 360px;
    display: flex;
    flex-direction: column;
}

.fragment-cards-carousel .card-img {
    width: 100%;
    height: 135px;
    object-fit: cover;
    margin-bottom: 16px;
    display: block;
    border-radius: 0;
}

.fragment-cards-carousel .card-img-wrapper {
    border-top-left-radius: 3px;
    border-top-right-radius: 3px;
    overflow: hidden; /* mantém o raio no container */
}

.fragment-cards-carousel .card-content {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    flex-grow: 1;
    padding: 0 20px 14px 20px;
}

.fragment-cards-carousel .card-title {
    font-size: 16px;
    font-weight: bold;
    margin: 0 0 16px 0;
}

.fragment-cards-carousel .card-text {
    font-size: 16px;
    color: #5B5B5F;
    margin: 0 0 16px 0;
}

.fragment-cards-carousel .card-link {
    font-size: 16px;
    color: #0435AC;
    text-decoration: underline;
}

.fragment-cards-carousel .slick-prev:before,
.fragment-cards-carousel .slick-next:before {
    content: '';
}

.fragment-cards-carousel .slick-prev,
.fragment-cards-carousel .slick-next {
    z-index: 10;
    background-color: #1A171B;
    height: 40px;
    width: 40px;
    border-radius: 50%;
    display: flex !important;
    align-items: center;
    justify-content: center;
    opacity: 1; /* padrão ativo */
    transition: opacity 0.3s ease; /* animação suave */
}

.fragment-cards-carousel .slick-prev.slick-disabled,
.fragment-cards-carousel .slick-next.slick-disabled {
    opacity: 0.5; /* quando não há mais slides */
}

.fragment-cards-carousel .slick-prev img {
    transform: rotate(90deg); 
}

.fragment-cards-carousel .slick-next img {
    transform: rotate(-90deg);
}

.fragment-cards-carousel {
  visibility: hidden;
}

.fragment-cards-carousel.slick-initialized {
  visibility: visible;
}


@media (max-width: 768px) {
    .fragment-cards-carousel .custom-card {
        min-height: auto;
    }
    .fragment-cards-carousel .slick-prev {
        left: 0px;
    }
    .fragment-cards-carousel .slick-next {
        right: 0px;
    }
}

js:
$(document).ready(function () {
    const $carousel = $(".fragment-cards-carousel");
    const totalCards = $carousel.children().length;

    $carousel.slick({
        infinite: false,
        slidesToShow: 4,
        slidesToScroll: 1,
        arrows: totalCards > 4,
        prevArrow: '<a type="button" class="slick-prev"><img loading="lazy" alt="seta apontando para esquerda" src="data:image/svg+xml;base64,"></a>',
        nextArrow: '<a type="button" class="slick-next"><img loading="lazy" alt="seta apontando para direita" src="data:image/svg+xml;base64,"></a>',
        responsive: [
            {
                breakpoint: 768,
                settings: {
                    slidesToShow: 1,
                    slidesToScroll: 1,
                    arrows: totalCards > 1
                }
            }
        ]
    });
});;

