js:
$(document).ready(function () {
    $("#successSendMessage").hide();
    $("#erroSendMessage").hide();
    $('#cxtelefone').mask('(00) 0000-00000');
    $('#submitBtn').click(function () {
        $(".error-message").remove();
        $(".form-control").removeClass("error-border");
        validateForm();

        // Verificar se o reCAPTCHA foi marcado
        if (grecaptcha.getResponse() === "") {
            $("<p class='error-message recaptcha-error' style='text-align: center;'>Por favor, confirme que você não é um robô.</p>").insertAfter(".recaptcha-container");
            return;
        }

        if ($(".error-message").length === 0) {
            $('#submitBtn').prop('disabled', true);
            submitForm();
        }
    });

    function submitForm() {
        var apiURL = window.location.origin.toString() + "/api/servicos/palestras-cursos/send-portal-do-corretor-email";
        var selectRegiaoAtuacao = $('#cxSelectRegiaoAtuacao').val();
        var nomeCompleto = $('#cxNomeCompleto').val();
        var email = $('#cxemail').val();
        var telefone = $('#cxtelefone').val().replace(/\D/g, '');
        var subject = 'Portal do Corretor - Quero ser um corretor';
				var emailDestino =  $('#cxSelectRegiaoAtuacao option:selected').data('emaildestino');
        var data = {
            emailTo: email,
            internalEmail: emailDestino == "" ? configuration.emailInterno : emailDestino +';'+configuration.emailInterno,
            nomeCompleto: nomeCompleto,
            telefone: telefone,
            regiaoAtuacao: selectRegiaoAtuacao,
            subject: subject,
					  tabelaDinamica: "Quero Ser Corretor",
					  groupId: window.__SITE__.codigo,
					  userId: '',
					  companyId: ''
        };
        var requestOptions = {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(data),
            redirect: 'follow'
        };

        fetch(apiURL, requestOptions)
            .then(response => response.ok ? response.json() : Promise.reject(response.text()))
            .then(result => {
                $('#submitBtn').prop('disabled', false);
                if (result) {
                    $("#submitFormDiv").hide();
                    $("#successSendMessage").show();
                    //var protocolo = result.Ds_registro;
                    //$("#protocolo").html("O número do seu Protocolo é <strong>" + protocolo + "</strong>");
                } else {
                    throw new Error('Resposta da API está vazia ou não pode ser processada.');
                }
            })
            .catch(error => {
                $('#submitBtn').prop('disabled', false);
                console.error('Erro na requisição:', error);
                $("#erroSendMessage").show();
            });
    }

function validateForm() {
        if ($("#cxSelectRegiaoAtuacao").val() === "" || $("#cxSelectRegiaoAtuacao").val() === null) {
            $("<p class='error-message'>Por favor, selecione uma região de atuação.</p>").insertAfter("#cxSelectRegiaoAtuacao");
            $("#cxSelectRegiaoAtuacao").addClass("error-border");
        } else {
            $("#cxSelectRegiaoAtuacao").removeClass("error-border");
        }

        if ($("#cxNomeCompleto").val() === "") {
            $("<p class='error-message'>Por favor, insira o nome completo.</p>").insertAfter("#cxNomeCompleto");
            $("#cxNomeCompleto").addClass("error-border");
        }

        var telefone = $("#cxtelefone").val();
        var telefoneRegex = /^\(\d{2}\)\s*\d{4}-?\d{4,5}$/;
        if (telefone.trim() === "") {
            $("<p class='error-message'>Por favor, preencha o campo de telefone/celular.</p>").insertAfter("#cxtelefone");
            $("#cxtelefone").addClass("error-border");
        } else if (!telefoneRegex.test(telefone)) {
            $("<p class='error-message'>Formato de telefone/celular inválido. Por favor, insira no formato (99) 9999-99999.</p>").insertAfter("#cxtelefone");
            $("#cxtelefone").addClass("error-border");
        }

        var email = $("#cxemail").val();
        if (email.trim() === "") {
            $("<p class='error-message'>Por favor, preencha o campo de e-mail.</p>").insertAfter("#cxemail");
            $("#cxemail").addClass("error-border");
        } else if (!isValidEmail(email)) {
            $("<p class='error-message'>E-mail inválido.</p>").insertAfter("#cxemail");
            $("#cxemail").addClass("error-border");
        }
    }

    function isValidEmail(email) {
        var emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }
});;

