.fhdj-cardsQualiServicos{
position: relative;
}
.fhdj-cardsQualiServicos .slick-list{
display:flex;
	width: 100%;
}
.fhdj-cardsQualiServicos .slick-track{
display:flex;
/*column-gap: 30px;*/
	width:100%;
}
		.fhdj-cardsQualiServicos .slick-track .fhdj-blocoQuali + .fhdj-blocoQuali{
	 margin-left:30px!important;
	}
.fhdj-cardsQualiServicos .slick-slide{
height:auto;
}
.fhdj-cardsQualiServicos .fhdj-blocoQualiTexto {
display: flex;
flex-direction: column;
height: 100%;
}

.fhdj-cardsQualiServicos .fhdj-arrow_prevQuali span, .fhdj-cardsQualiServicos .fhdj-arrow_nextQuali span{
display: inline-block;
width: 30px;
height: 30px;
line-height:26px;
background-color: #2D2D2D;
overflow:hidden;
cursor: pointer;
}

.fhdj-cardsQualiServicos .fhdj-sliderQualiServicos .fhdj-blocoQuali{
background: #FFFFFF 0% 0% no-repeat padding-box;
box-shadow: 0px 3px 6px #0000004A;
border-radius: 3px;
min-height: 191px;
width:100%;
}

/*Custom slick*/
.fhdj-cardsQualiServicos .fhdj-arrow_prevQuali, .fhdj-cardsQualiServicos .fhdj-arrow_nextQuali {
position: absolute;
bottom: 50%;
border: none;
background: transparent;
height:30px;
padding:2px;
}
.fhdj-cardsQualiServicos button:focus-visible, .fhdj-cardsQualiServicos button:focus-visible{
outline: auto!important;
}
.fhdj-cardsQualiServicos button:focus{
outline-width: medium;
outline-style: none;
outline-color: invert;
}
.fhdj-cardsQualiServicos .fhdj-arrow_nextQuali {
right: -3%;
}
.fhdj-cardsQualiServicos .fhdj-arrow_prevQuali{
right: initial;
left: -3%;
}

.fhdj-cardsQualiServicos .fhdj-sliderQualiServicos .slick-dots li button:before{
font-size: 12px;
}
.fhdj-cardsQualiServicos .fhdj-sliderQualiServicos .slick-dots li.slick-active button:before{
color:#0054B8;
font-size: 12px;
background-color: var(--primary)!important;
border-radius: 2px;
opacity:1;
}

.fhdj-cardsQualiServicos .fhdj-arrow_prevQuali.slick-arrow.slick-disabled, .fhdj-cardsQualiServicos .fhdj-arrow_nextQuali.slick-arrow.slick-disabled{
opacity:0.25;
}
.fhdj-cardsQualiServicos .fhdj-arrow_prevQuali,
.fhdj-cardsQualiServicos .fhdj-arrow_nextQuali {
display: none;
}

.fhdj-cardsQualiServicos .fhdj-sliderQualiServicos .slick-dots li button:before{
border: 1px solid var(--primary)!important;
content:"";
border-radius: 2px;
width: 10px;
height: 10px;
}
.fhdj-cardsQualiServicos .fhdj-sliderQualiServicos .slick-dots li button:hover:before, .fhdj-cardsQualiServicos .fhdj-sliderQualiServicos .slick-dots li button:focus:before{
color:initial;
}

